class Solution {
  public int minCost(int[] nums1, int[] nums2) {
    int MAX = 80_001;
    int[] c1 = new int[MAX], total = new int[MAX];
    for (int v : nums1) {
      c1[v]++;
      total[v]++;
    }
    for (int v : nums2) total[v]++;
    int excess = 0;
    for (int v = 0; v < MAX; v++) {
      if (total[v] % 2 != 0) return -1;
      excess += Math.max(0, c1[v] - total[v] / 2);
    }
    return excess;
  }
}
